/**
 * Mock GIF provider (Phase 4): 8 real animated fixtures from `public/gif-fixtures/` (generated by
 * `npm run gif:fixtures`), served same-origin. Used whenever no Klipy key is configured (or when
 * localStorage `matrix-poc.gifProvider` = 'mock'), so the whole feature works offline and in tests.
 *
 * Contract (docs/archive/PHASE4_ACCEPTANCE.md): `trending` returns all 8 in catalogue order; `search` is a case-insensitive
 * title substring match in the same order (empty query = everything); `nothing-here` / `__empty__` -> `[]`; `__error__`
 * rejects with `GifProviderError('network', 'mock: simulated failure')`; `page > 1` -> `[]`; `nextPage` null / `hasNext` false; resolves
 * within 50 ms (next microtask unless `delayMs` is set). `previewUrl` = the gif, `stillUrl` = the png.
 *
 * Pure module: pass `baseUrl` from Node (`http://localhost:5173`); in the browser it defaults to
 * `location.origin` + the Vite base path.
 */
import { MOCK_EMPTY_QUERIES, MOCK_ERROR_QUERY, MOCK_FIXTURES, MOCK_FIXTURE_PATH } from './mock-fixtures.ts';
import { GifProviderError } from './types.ts';
import type { GifPage, GifProvider, GifQueryOptions, GifResult } from './types.ts';

export interface MockProviderOptions {
  /** Origin (+ base path) the fixtures are served from, no trailing slash needed. Default: `location.origin` + `basePath`. */
  baseUrl?: string;
  /** Vite `BASE_URL` (`'/'` by default). Only used when `baseUrl` is not given. */
  basePath?: string;
  /** Artificial latency in ms (QA: loading states). Default 0. */
  delayMs?: number;
}

function resolveBase(opts: MockProviderOptions): string {
  if (opts.baseUrl) return opts.baseUrl.replace(/\/+$/, '') + '/';
  const loc = (globalThis as { location?: { origin?: string } }).location;
  const origin = loc?.origin ?? 'http://localhost:5173';
  const base = (opts.basePath ?? '/').replace(/\/+$/, '') + '/';
  return origin + base;
}

/** Absolute fixture URLs for the catalogue. */
export function mockGifResults(opts: MockProviderOptions = {}): GifResult[] {
  const base = resolveBase(opts);
  return MOCK_FIXTURES.map((f) => {
    const url = `${base}${MOCK_FIXTURE_PATH}${f.id}.gif`;
    return {
      id: f.id,
      title: f.title,
      previewUrl: url,
      previewMimetype: 'image/gif',
      previewW: f.width,
      previewH: f.height,
      fullUrl: url,
      fullW: f.width,
      fullH: f.height,
      stillUrl: `${base}${MOCK_FIXTURE_PATH}${f.id}.png`,
      mimetype: 'image/gif',
      provider: 'mock',
    };
  });
}

export function createMockProvider(opts: MockProviderOptions = {}): GifProvider {
  const all = mockGifResults(opts);
  const page = async (results: GifResult[], q?: GifQueryOptions): Promise<GifPage> => {
    if (opts.delayMs) await new Promise((r) => setTimeout(r, opts.delayMs));
    if (q?.signal?.aborted) throw new GifProviderError('aborted', 'Request aborted');
    const pageNo = Number(q?.page ?? 1);
    return { results: pageNo > 1 ? [] : results, nextPage: null, hasNext: false };
  };
  return {
    name: 'mock',
    async search(query, q) {
      const needle = query.trim().toLowerCase();
      if (needle === MOCK_ERROR_QUERY) {
        if (opts.delayMs) await new Promise((r) => setTimeout(r, opts.delayMs));
        throw new GifProviderError('network', 'mock: simulated failure');
      }
      if (MOCK_EMPTY_QUERIES.includes(needle)) return page([], q);
      return page(needle ? all.filter((g) => g.title.toLowerCase().includes(needle)) : all, q);
    },
    trending(q) {
      return page(all, q);
    },
  };
}
